def lpHaarPartitionAverage (hp : p ≠ ∞) (s : Set α) : Lp 𝕜 p μ →L[𝕜] 𝕜 :=
  (μ.real s : 𝕜)⁻¹ • ((lpHaarFiniteIntegral (μ := μ.restrict s) hp).comp
    (lebesgueLpRestrict (𝕜 := 𝕜) s))

